var i=`0464-bulgur-pilav`;var n=`world-0464`;var o=`TR`;var r=`western-asia`;var a=4;var s=42;var l={en:`Bulgur Pilavı`,ua:`Булгурний плов`};var u={en:`A traditional dish from Türkiye, centered on yellow onion, tomato paste, bulgur, green bell pepper. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Туреччина. Основні складники: жовта цибуля, томатна паста, булгур, зелений солодкий перець. Домашній варіант із кількостями продуктів за етапами приготування.`};var g=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,160,`g`],[`extra-virgin-olive-oil`,45,`ml`],[`tomato-paste`,30,`g`]]},{en:`Add bulgur to the softened aromatics and hot stock; cover and simmer until the bulgur absorbs the liquid and becomes tender.`,ua:`Всипте булгур до припущених овочів та гарячого бульйону, накрийте й томіть до вбирання рідини та м’якості крупи.`,t:[`rice-washing`,`absorption-cooking`],m:22,i:[[`bulgur`,360,`g`],[`chicken-stock`,700,`ml`],[`green-bell-pepper`,120,`g`],[`tomato`,170,`g`]]},{en:`Take off the heat and let the rice rest under a clean towel or lid for about 10 minutes before serving.`,ua:`Зніміть із вогню та дайте рису відпочити під чистим рушником або кришкою приблизно 10 хвилин перед подаванням.`,t:[`rice-resting`,`fluffing-grains`],m:10,i:[[`unsalted-butter`,35,`g`]]}];var d={slug:i,id:n,country:`TR`,region:r,servings:4,minutes:42,title:l,text:u,steps:g};export{o as country,d as default,n as id,s as minutes,r as region,a as servings,i as slug,g as steps,u as text,l as title};